#!/usr/bin/env python3
"""Finish mail-inbox http_server.cpp patches on the live droplet tree."""
import gzip, base64, json, shutil
from pathlib import Path
from datetime import datetime, timezone

BLOB = """"""

DATA = json.loads(gzip.decompress(base64.b64decode(BLOB)))
src = Path("/opt/liquidgov/src/http_server.cpp")
stamp = datetime.now(timezone.utc).strftime("%Y%m%dT%H%M%SZ")
fail = []

def once(name, text, old, new):
    n = text.count(old)
    print(name, n)
    if n == 0:
        if new and text.count(new) >= 1:
            print("  already")
            return text
        fail.append(name)
        return text
    if n != 1:
        fail.append(name + " count=" + str(n))
        return text
    return text.replace(old, new, 1)

def span_rep(name, text, start, end, new):
    ns, ne = text.count(start), text.count(end)
    print(name, "start", ns, "end", ne)
    if text.count(new) >= 1 and ns == 0:
        print("  already")
        return text
    if ns != 1 or ne != 1:
        fail.append(name)
        return text
    i, j = text.find(start), text.find(end)
    if i < 0 or j < 0 or i >= j:
        fail.append(name + " order")
        return text
    return text[:i] + new + text[j:]

if not src.exists():
    raise SystemExit("no http_server.cpp")
shutil.copy2(src, str(src) + ".bak-mailv2-" + stamp)
t = src.read_text()
for item in DATA["spans"]:
    t = span_rep("http:" + item["name"], t, item["start"], item["end"], item["new"])
for item in DATA["http_slices"]:
    t = once("http:" + item["name"], t, item["old"], item["new"])
for item in DATA["http_small"]:
    t = once("http:" + item["name"], t, item["old"], item["new"])
if fail:
    print("STOP", ", ".join(fail))
    print("NEED_BUILD 0")
    raise SystemExit(1)
src.write_text(t)
print("ok wrote http_server.cpp bak-mailv2-" + stamp)
print("NEED_BUILD 1")
